import os
import sqlite3
import pandas as pd
import numpy as np

# First, let's explore the directory structure to understand what's available
print("Current working directory:", os.getcwd())
print("\nListing root directory:")
try:
    root_files = os.listdir('/')
    for item in root_files:
        print(f"  - {item}")
except Exception as e:
    print(f"Error: {e}")

print("\nChecking for data directories:")
# Check common data directories
possible_dirs = ['/data', '/mnt', '/home', '/root', '.', '..']
for dir_path in possible_dirs:
    if os.path.exists(dir_path):
        print(f"\n{dir_path} exists. Contents:")
        try:
            contents = os.listdir(dir_path)
            for item in contents[:10]:  # Show first 10 items
                print(f"  - {item}")
            if len(contents) > 10:
                print(f"  ... and {len(contents) - 10} more items")
        except Exception as e:
            print(f"  Error listing: {e}")

# Let's check if there are any SQLite files in the current directory
print("\nSearching for SQLite files in current directory and subdirectories:")
sqlite_files = []
for root, dirs, files in os.walk('.'):
    for file in files:
        if file.endswith(('.db', '.sqlite', '.sqlite3')):
            full_path = os.path.join(root, file)
            sqlite_files.append(full_path)
            print(f"  Found: {full_path}")

if sqlite_files:
    print(f"\nFound {len(sqlite_files)} SQLite database(s). Using the first one.")
    db_path = sqlite_files[0]
else:
    print("\nNo SQLite databases found. Let's check for any data files.")
    # Look for any data files
    data_files = []
    for root, dirs, files in os.walk('.'):
        for file in files:
            if file.endswith(('.csv', '.xlsx', '.xls', '.json', '.parquet')):
                full_path = os.path.join(root, file)
                data_files.append(full_path)

    if data_files:
        print(f"\nFound {len(data_files)} data file(s):")
        for file in data_files[:5]:  # Show first 5
            print(f"  - {file}")
        print("\nWe'll need to load one of these files instead of a SQLite database.")
    else:
        print("\nNo data files found either. Please check the file structure.")
